window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[32]={"3200":{"example:3200:exzh":"He is an outstanding disciple.","example:3200:exzh2":"I teach the disciples a lot.","example:3200:exzh3":"That disciple is very eager to learn.","example:3200:exzh4":"I want to be a mentor the disciples can trust.","example:3200:exzh5":"Raising disciples is extremely important."},"3201":{"example:3201:exzh":"The forecast for today is sunny.","example:3201:exzh2":"On sunny days I want to go outside.","example:3201:exzh3":"I like looking up at the sky on sunny days.","example:3201:exzh4":"It looks like it'll be sunny this weekend.","example:3201:exzh5":"Sunny days are perfect for a picnic.","grammar:3201:ex:trans":"Today's forecast is sunny.","grammar:3201:ex:structure":"nounは＋〔晴れの予報〕＋です.","grammar:3201:ex:explain":"This is an 「AはBです」 sentence. 「晴れの予報」 = the forecast for sunny weather, joining two nouns with 「の」 as the predicate. 「晴れ」 is a noun (sunny weather). 「今日は」 presents today as the topic with 「は」. The whole sentence means today's forecast is sunny.","grammar:3201:ex:words:0:zh":"today","grammar:3201:ex:words:0:note":"きょう","grammar:3201:ex:words:0:pos":"noun","grammar:3201:ex:words:1:zh":"(topic marker)","grammar:3201:ex:words:1:pos":"particle","grammar:3201:ex:words:2:zh":"sunny weather / clear skies","grammar:3201:ex:words:2:note":"はれ","grammar:3201:ex:words:2:pos":"noun","grammar:3201:ex:words:3:zh":"'s","grammar:3201:ex:words:3:pos":"particle","grammar:3201:ex:words:4:zh":"forecast","grammar:3201:ex:words:4:note":"よほう","grammar:3201:ex:words:4:pos":"noun","grammar:3201:ex:words:5:zh":"is","grammar:3201:ex:words:5:pos":"copula","grammar:3201:ex:points:0":"晴れ: sunny weather (noun)","grammar:3201:ex:points:1":"晴れの予報: a sunny forecast","grammar:3201:ex2:trans":"On sunny days, I want to go out.","grammar:3201:ex2:structure":"〔晴れの日〕＋は、nounに＋verbたい. 「〜たい」 expresses desire.","grammar:3201:ex2:words:0:zh":"sunny weather / clear skies","grammar:3201:ex2:words:0:note":"はれ","grammar:3201:ex2:words:0:pos":"noun","grammar:3201:ex2:words:1:zh":"'s","grammar:3201:ex2:words:1:pos":"particle","grammar:3201:ex2:words:2:zh":"day","grammar:3201:ex2:words:2:note":"ひ","grammar:3201:ex2:words:2:pos":"noun","grammar:3201:ex2:words:3:zh":"(topic marker)","grammar:3201:ex2:words:3:pos":"particle","grammar:3201:ex2:words:4:zh":"outside","grammar:3201:ex2:words:4:note":"そと","grammar:3201:ex2:words:4:pos":"noun","grammar:3201:ex2:words:5:zh":"(direction)","grammar:3201:ex2:words:5:pos":"particle","grammar:3201:ex2:words:6:zh":"want to go out","grammar:3201:ex2:words:6:note":"でかけたい; 〜たい (desire)","grammar:3201:ex2:words:6:pos":"verb","grammar:3201:ex2:points:0":"晴れの日: a sunny day","grammar:3201:ex2:points:1":"〜たい: want to …","grammar:3201:ex3:trans":"I like looking up at the sky on sunny days.","grammar:3201:ex3:structure":"〜日に〜を見上げるのが好きです","grammar:3201:ex3:explain":"「晴れの日」 means a sunny day, and 「に」 marks the time when you look up at the sky. 「空を見上げる」 is a single action, nominalized by the 「の」 after it and marked with 「が」 as the thing that is liked. 「好きです」 says it is a personal preference.","grammar:3201:ex3:words:0:zh":"sunny weather / clear skies","grammar:3201:ex3:words:0:note":"はれ","grammar:3201:ex3:words:0:pos":"noun","grammar:3201:ex3:words:1:zh":"(links nouns)","grammar:3201:ex3:words:1:pos":"particle","grammar:3201:ex3:words:2:zh":"day","grammar:3201:ex3:words:2:note":"ひ","grammar:3201:ex3:words:2:pos":"noun","grammar:3201:ex3:words:3:zh":"(time of the action)","grammar:3201:ex3:words:3:pos":"particle","grammar:3201:ex3:words:4:zh":"sky","grammar:3201:ex3:words:4:note":"そら","grammar:3201:ex3:words:4:pos":"noun","grammar:3201:ex3:words:5:zh":"(object)","grammar:3201:ex3:words:5:pos":"particle","grammar:3201:ex3:words:6:zh":"to look up","grammar:3201:ex3:words:6:note":"みあげる","grammar:3201:ex3:words:6:pos":"verb","grammar:3201:ex3:words:7:zh":"(nominalizer)","grammar:3201:ex3:words:7:pos":"particle","grammar:3201:ex3:words:8:zh":"(the thing liked)","grammar:3201:ex3:words:8:pos":"particle","grammar:3201:ex3:words:9:zh":"to like","grammar:3201:ex3:words:9:note":"すき","grammar:3201:ex3:words:9:pos":"na-adjective","grammar:3201:ex3:words:10:zh":"(polite affirmative judgment)","grammar:3201:ex3:words:10:pos":"auxiliary verb","grammar:3201:ex3:points:0":"「verb dictionary form + のが好きです」 expresses liking to do something.","grammar:3201:ex3:points:1":"The first 「の」 links nouns; the second 「の」 nominalizes the action.","grammar:3201:ex3:points:2":"「見上げる」 means to direct your gaze upward, and what you look at takes 「を」.","grammar:3201:ex4:trans":"It looks like it will be sunny this weekend.","grammar:3201:ex4:structure":"〜はnounになりそうだ","grammar:3201:ex4:explain":"「週末は」 presents the weekend as the topic of the prediction. 「晴れになる」 means the weather turns sunny, with 「に」 marking the resulting state. 「なる」 changes to 「なり」 and takes the evidential auxiliary 「そうだ」, showing that, based on current information or signs, the weekend looks like it will clear up.","grammar:3201:ex4:words:0:zh":"weekend","grammar:3201:ex4:words:0:note":"しゅうまつ","grammar:3201:ex4:words:0:pos":"noun","grammar:3201:ex4:words:1:zh":"(topic)","grammar:3201:ex4:words:1:pos":"particle","grammar:3201:ex4:words:2:zh":"sunny weather / clear skies","grammar:3201:ex4:words:2:note":"はれ","grammar:3201:ex4:words:2:pos":"noun","grammar:3201:ex4:words:3:zh":"(result of the change)","grammar:3201:ex4:words:3:pos":"particle","grammar:3201:ex4:words:4:zh":"become","grammar:3201:ex4:words:4:pos":"verb","grammar:3201:ex4:words:5:zh":"(looks like; conjecture from signs)","grammar:3201:ex4:words:5:pos":"auxiliary verb","grammar:3201:ex4:words:6:zh":"(plain form, affirmative)","grammar:3201:ex4:words:6:pos":"auxiliary verb","grammar:3201:ex4:points:0":"「noun＋になる」 means to become a certain state.","grammar:3201:ex4:points:1":"「verb masu-form without ます＋そうだ」 means something looks like it will happen.","grammar:3201:ex4:points:2":"「なりそうだ」 is a guess based on signs, different from 「なるそうだ」, which reports hearsay.","grammar:3201:ex5:trans":"Sunny days are perfect for a picnic.","grammar:3201:ex5:structure":"〔晴れの日〕＋は＋noun＋に＋na-adjective. 「〜に最適」 = perfect for …","grammar:3201:ex5:words:0:zh":"sunny weather / clear skies","grammar:3201:ex5:words:0:note":"はれ","grammar:3201:ex5:words:0:pos":"noun","grammar:3201:ex5:words:1:zh":"'s","grammar:3201:ex5:words:1:pos":"particle","grammar:3201:ex5:words:2:zh":"day","grammar:3201:ex5:words:2:note":"ひ","grammar:3201:ex5:words:2:pos":"noun","grammar:3201:ex5:words:3:zh":"(topic marker)","grammar:3201:ex5:words:3:pos":"particle","grammar:3201:ex5:words:4:zh":"picnic","grammar:3201:ex5:words:4:note":"loanword","grammar:3201:ex5:words:4:pos":"noun","grammar:3201:ex5:words:5:zh":"(target / aspect)","grammar:3201:ex5:words:5:pos":"particle","grammar:3201:ex5:words:6:zh":"best suited for","grammar:3201:ex5:words:6:note":"さいてき","grammar:3201:ex5:words:6:pos":"na-adjective","grammar:3201:ex5:points:0":"〜に最適: perfect for …","grammar:3201:ex5:points:1":"晴れの日: a sunny day","exam:3201:zh":"It's been sunny since morning today, with no clouds in the sky, so the sun is clearly visible.","exam:3201:why":"「晴れ」 means sunny, which fits the description of no clouds and a visible sun. 「曇り」 means cloudy, when there are clouds in the sky."},"3202":{"example:3202:exzh":"On my days off, I made full use of my time to study.","example:3202:exzh2":"He charged his phone to full.","example:3202:exzh3":"He'll start working full-time next month.","example:3202:exzh4":"My schedule is already full this week, so I can't take on any new work.","example:3202:exzh5":"I finished my first full marathon."},"3203":{"example:3203:exzh":"He received a huge inheritance.","example:3203:exzh2":"It's important to protect cultural heritage.","example:3203:exzh3":"This heritage is historically very important.","example:3203:exzh4":"You need to go through the procedures for inheriting an estate.","example:3203:exzh5":"Some families have very little inheritance."},"3204":{"example:3204:exzh":"Phosphorus is one of the chemical elements.","example:3204:exzh2":"Phosphoric acid is used in fertilizer.","example:3204:exzh3":"Phosphorus is a substance essential for life.","example:3204:exzh4":"Phosphorus is contained in many compounds.","example:3204:exzh5":"Phosphorus metabolism is important."},"3205":{"example:3205:exzh":"He created a new idea.","example:3205:exzh2":"We need the ability to create new value.","example:3205:exzh3":"She created her own unique music.","example:3205:exzh4":"Researchers are trying to create the technology of the future.","example:3205:exzh5":"I took part in an activity that creates local culture."},"3206":{"example:3206:exzh":"Sedatives are used in medicine.","example:3206:exzh2":"He needs sedation.","example:3206:exzh3":"Some medicines have a sedative effect.","example:3206:exzh4":"Calming yourself helps relieve stress.","example:3206:exzh5":"It's important to learn ways to calm yourself."},"3207":{"example:3207:exzh":"You need to keep things secured in place.","example:3207:exzh2":"I secured the car's tires.","example:3207:exzh3":"This device is used to hold things in place.","example:3207:exzh4":"It's dangerous if it isn't secured.","example:3207:exzh5":"I secured the table."},"3209":{"example:3209:exzh":"I hammered in a nail with a hammer.","example:3209:exzh2":"A hammer is one of the tools.","example:3209:exzh3":"This hammer is very heavy.","example:3209:exzh4":"I'm good at using a hammer.","example:3209:exzh5":"I fix broken things with a hammer."},"3210":{"example:3210:exzh":"Let's act without panicking.","example:3210:exzh2":"He left the house in a panic.","example:3210:exzh3":"Don't panic over trouble.","example:3210:exzh4":"When you panic, you make more mistakes.","example:3210:exzh5":"I wrote the report in a hurry.","grammar:3210:ex:trans":"Don't panic — let's act.","grammar:3210:ex:structure":"慌てずに行動しましょう","grammar:3210:ex:explain":"The key here is 「〜ずに」, which attaches to the nai-stem of a verb and works like 「〜ないで」, meaning without doing… (and doing something else); it sounds slightly more formal and concise. 「慌てる（あわてる）」 is the intransitive verb to panic, so 「慌てず」 = without panicking, and adding 「に」 makes it adverbial: calmly. The ending 「行動しましょう」 uses the volitional 「〜ましょう」, meaning let's…. The whole sentence means don't panic, let's act calmly, and it is often used to reassure or remind someone.","grammar:3210:ex:words:0:zh":"without panicking","grammar:3210:ex:words:0:note":"あわてず","grammar:3210:ex:words:0:pos":"verb","grammar:3210:ex:words:1:zh":"(manner)","grammar:3210:ex:words:1:pos":"particle","grammar:3210:ex:words:2:zh":"let's act","grammar:3210:ex:words:2:note":"こうどうしましょう","grammar:3210:ex:words:2:pos":"verb","grammar:3210:ex:points:0":"❗慌てる（あわてる, read あわてる）: to panic, to rush (intransitive verb); 〜ずに = without… (慌てず = calmly).","grammar:3210:ex:points:1":"慌てずに: calmly.","grammar:3210:ex2:trans":"He hurried out of the house.","grammar:3210:ex2:structure":"慌てて〜を出ました","grammar:3210:ex2:words:0:zh":"he","grammar:3210:ex2:words:0:note":"かれ","grammar:3210:ex2:words:0:pos":"pronoun","grammar:3210:ex2:words:1:zh":"(topic)","grammar:3210:ex2:words:1:pos":"particle","grammar:3210:ex2:words:2:zh":"in a hurry","grammar:3210:ex2:words:2:note":"あわてて","grammar:3210:ex2:words:2:pos":"verb","grammar:3210:ex2:words:3:zh":"house","grammar:3210:ex2:words:3:note":"いえ","grammar:3210:ex2:words:3:pos":"noun","grammar:3210:ex2:words:4:zh":"(starting point)","grammar:3210:ex2:words:4:pos":"particle","grammar:3210:ex2:words:5:zh":"left","grammar:3210:ex2:words:5:note":"でました","grammar:3210:ex2:words:5:pos":"verb","grammar:3210:ex2:points:0":"❗慌てて: in a panic (the te-form of 慌てる); 家を出る = to leave the house.","grammar:3210:ex2:points:1":"慌てて出る: to rush out.","grammar:3210:ex3:trans":"Don't panic over trouble.","grammar:3210:ex3:structure":"〜に慌てないで","grammar:3210:ex3:words:0:zh":"trouble","grammar:3210:ex3:words:0:note":"loanword","grammar:3210:ex3:words:0:pos":"noun","grammar:3210:ex3:words:1:zh":"(object)","grammar:3210:ex3:words:1:pos":"particle","grammar:3210:ex3:words:2:zh":"don't panic","grammar:3210:ex3:words:2:note":"あわてないで","grammar:3210:ex3:words:2:pos":"verb","grammar:3210:ex3:points:0":"❗〜に慌てる: to panic over…; 〜ないで = don't…","grammar:3210:ex3:points:1":"慌てないで: don't panic.","grammar:3210:ex4:trans":"When you panic, you make more mistakes.","grammar:3210:ex4:structure":"慌てると〜が増えます","grammar:3210:ex4:words:0:zh":"panic","grammar:3210:ex4:words:0:note":"あわてる","grammar:3210:ex4:words:0:pos":"verb","grammar:3210:ex4:words:1:zh":"(as soon as…)","grammar:3210:ex4:words:1:pos":"particle","grammar:3210:ex4:words:2:zh":"mistake","grammar:3210:ex4:words:2:note":"loanword","grammar:3210:ex4:words:2:pos":"noun","grammar:3210:ex4:words:3:zh":"(nominative)","grammar:3210:ex4:words:3:pos":"particle","grammar:3210:ex4:words:4:zh":"increase","grammar:3210:ex4:words:4:note":"ふえます","grammar:3210:ex4:words:4:pos":"verb","grammar:3210:ex4:points:0":"❗〜と: as soon as…, then…; ミスが増える = mistakes increase.","grammar:3210:ex4:points:1":"慌てると: once you panic.","grammar:3210:ex5:trans":"I wrote the report in a hurry.","grammar:3210:ex5:structure":"慌てて〜を書きました","grammar:3210:ex5:words:0:zh":"in a hurry","grammar:3210:ex5:words:0:note":"あわてて","grammar:3210:ex5:words:0:pos":"verb","grammar:3210:ex5:words:1:zh":"written report","grammar:3210:ex5:words:1:note":"ほうこくしょ","grammar:3210:ex5:words:1:pos":"noun","grammar:3210:ex5:words:2:zh":"(object marker)","grammar:3210:ex5:words:2:pos":"particle","grammar:3210:ex5:words:3:zh":"wrote","grammar:3210:ex5:words:3:note":"かきました","grammar:3210:ex5:words:3:pos":"verb","grammar:3210:ex5:points:0":"❗慌てて書く: to write in a hurry; 報告書 = report.","grammar:3210:ex5:points:1":"慌てて書く: to write hastily."},"3211":{"example:3211:exzh":"A forensic examination of the case was carried out.","example:3211:exzh2":"He is waiting for the results of the forensic examination.","example:3211:exzh3":"Forensic examination methods vary widely.","example:3211:exzh4":"A major accident requires a forensic examination.","example:3211:exzh5":"The forensic examination will reveal the truth."},"3213":{"example:3213:exzh":"Industry in this region is developing.","example:3213:exzh2":"Some countries have strong industries.","example:3213:exzh3":"He is studying about industry.","example:3213:exzh4":"The Industrial Revolution happened.","example:3213:exzh5":"We will support new industries."},"3214":{"example:3214:exzh":"There's an interview tomorrow.","example:3214:exzh2":"He was nervous during the interview.","example:3214:exzh3":"You have to prepare for the interview.","example:3214:exzh4":"Many people have interviews.","example:3214:exzh5":"I'm waiting for the interview results."},"3215":{"example:3215:exzh":"This product is very popular.","example:3215:exzh2":"A new product will go on sale.","example:3215:exzh3":"Product quality is important.","example:3215:exzh4":"Please read the product manual.","example:3215:exzh5":"That product is expensive."},"3216":{"example:3216:exzh":"Interference is sometimes necessary.","example:3216:exzh2":"He hates interference from others.","example:3216:exzh3":"It's important to avoid interference.","example:3216:exzh4":"Political interference caused a problem.","example:3216:exzh5":"I don't want to be interfered with."},"3217":{"example:3217:exzh":"A new fact was discovered.","example:3217:exzh2":"He tried to find out the information.","example:3217:exzh3":"Detection is important.","example:3217:exzh4":"Detecting data is difficult.","example:3217:exzh5":"You have to keep detecting."},"3218":{"example:3218:exzh":"This dish is light and refreshing.","example:3218:exzh2":"He has a frank, easygoing personality.","example:3218:exzh3":"I completely forgot.","example:3218:exzh4":"I like light, refreshing flavors.","example:3218:exzh5":"She is dressed in a neat, simple outfit."},"3219":{"example:3219:exzh":"Sometimes you feel a sense of guilt.","example:3219:exzh2":"He can't escape from evil.","example:3219:exzh3":"Committing evil is not allowed.","example:3219:exzh4":"I'm tormented by guilt.","example:3219:exzh5":"She feels guilty."},"3220":{"example:3220:exzh":"The number of students in this class is 20.","example:3220:exzh2":"The number of employees at his company has increased.","example:3220:exzh3":"When there are a lot of people, meetings get tough.","example:3220:exzh4":"The event has a limit on the number of participants.","example:3220:exzh5":"It's important to know the exact number of people."},"3221":{"example:3221:exzh":"The two of them decided to reconcile.","example:3221:exzh2":"The issue is moving toward a settlement.","example:3221:exzh3":"The reconciliation process takes time.","example:3221:exzh4":"We held a meeting about the settlement.","example:3221:exzh5":"A settlement was reached in court."},"3222":{"example:3222:exzh":"This project cost a lot of money.","example:3222:exzh2":"He doesn't want to spend too much money on the trip.","example:3222:exzh3":"You need to find ways to keep costs down.","example:3222:exzh4":"Unexpected costs came up for this job.","example:3222:exzh5":"Managing costs is an important skill."},"3223":{"example:3223:exzh":"A virus was detected.","example:3223:exzh2":"This system can detect problems.","example:3223:exzh3":"The detection function needs to be strengthened.","example:3223:exzh4":"The effect of the medicine was detected.","example:3223:exzh5":"If an abnormality is detected, a warning is issued."},"3224":{"example:3224:exzh":"I admire his skillful technique.","example:3224:exzh2":"This clever design is very popular.","example:3224:exzh3":"His clever way of speaking is his strength.","example:3224:exzh4":"That project is being carried forward skillfully.","example:3224:exzh5":"It's important to use clever methods."},"3225":{"example:3225:exzh":"This cemetery has a long history.","example:3225:exzh2":"A cemetery is a quiet place.","example:3225:exzh3":"He visited the graves of his grandfather and grandmother.","example:3225:exzh4":"Good manners are important at a cemetery.","example:3225:exzh5":"There are many cemeteries in this area."},"3226":{"example:3226:exzh":"I hope his dream comes true.","example:3226:exzh2":"If you work hard, your wish will come true.","example:3226:exzh3":"A childhood dream has finally come true.","example:3226:exzh4":"Her wish came true.","example:3226:exzh5":"I'll do my best to make my dream come true."},"3227":{"example:3227:exzh":"I want to know where this information came from.","example:3227:exzh2":"It's best not to use data of unknown origin.","example:3227:exzh3":"He talks about things with a clear source.","example:3227:exzh4":"It's important to confirm the source.","example:3227:exzh5":"The source must be reliable."},"3229":{"example:3229:exzh":"He has a strict, serious personality.","example:3229:exzh2":"It's important to act cautiously.","example:3229:exzh3":"Please approach it with a careful, serious attitude.","example:3229:exzh4":"We respectfully inform you.","example:3229:exzh5":"Please speak respectfully at the meeting."},"3230":{"example:3230:exzh":"My conscience aches.","example:3230:exzh2":"He has a conscience.","example:3230:exzh3":"I act according to my conscience.","example:3230:exzh4":"It's important to stay true to your conscience.","example:3230:exzh5":"She runs an honest business."},"3231":{"example:3231:exzh":"The submission deadline is tomorrow.","example:3231:exzh2":"This project has a deadline.","example:3231:exzh3":"I intend to finish it by the deadline.","example:3231:exzh4":"Meeting the deadline is important.","example:3231:exzh5":"Once the deadline passes, it becomes invalid."},"3232":{"example:3232:exzh":"My lower back hurts.","example:3232:exzh2":"She is bending at the waist.","example:3232:exzh3":"Please take good care of your back.","example:3232:exzh4":"Let's do some stretches for our lower back.","example:3232:exzh5":"He may have strained his back."},"3233":{"example:3233:exzh":"We need to clarify the company's vision.","example:3233:exzh2":"His vision is the technology of the future.","example:3233:exzh3":"With a solid vision, a team comes together as one.","example:3233:exzh4":"We will take on the work with a new vision.","example:3233:exzh5":"Sharing the vision is important."},"3234":{"example:3234:exzh":"The Swiss scenery is beautiful.","example:3234:exzh2":"He lives in Switzerland.","example:3234:exzh3":"I love Swiss chocolate.","example:3234:exzh4":"Switzerland is a neutral country.","example:3234:exzh5":"Switzerland is famous for its snowy mountains.","grammar:3234:ex:trans":"The Swiss scenery is beautiful.","grammar:3234:ex:structure":"〔noun の noun〕＋は＋i-adjective＋です.","grammar:3234:ex:explain":"This is a basic 「AのBは＋i-adjective＋です」 description. 「スイスの風景」 uses 「の」 to modify, meaning \"the Swiss scenery,\" and is then presented as the topic with 「は」. The predicate 「美しい」 is an i-adjective meaning \"beautiful\" and takes 「です」 directly to become polite. Note that an i-adjective already carries the meaning \"is …\"; 「です」 only adds politeness and does not change the word's form (unlike na-adjectives, which need です／だ to work as a predicate). The whole sentence 「スイスの風景は美しいです」 = \"The Swiss scenery is beautiful.\"","grammar:3234:ex:words:0:zh":"Switzerland","grammar:3234:ex:words:0:note":"loanword","grammar:3234:ex:words:0:pos":"noun","grammar:3234:ex:words:1:zh":"'s","grammar:3234:ex:words:1:pos":"particle","grammar:3234:ex:words:2:zh":"scenery","grammar:3234:ex:words:2:note":"ふうけい","grammar:3234:ex:words:2:pos":"noun","grammar:3234:ex:words:3:zh":"(topic marker)","grammar:3234:ex:words:3:pos":"particle","grammar:3234:ex:words:4:zh":"beautiful","grammar:3234:ex:words:4:note":"うつくしい","grammar:3234:ex:words:4:pos":"adjective","grammar:3234:ex:words:5:zh":"(polite form)","grammar:3234:ex:words:5:pos":"copula","grammar:3234:ex:points:0":"スイスの風景: Swiss scenery","grammar:3234:ex:points:1":"美しい: beautiful","grammar:3234:ex2:trans":"He lives in Switzerland.","grammar:3234:ex2:structure":"〜は＋place＋に＋住んでいます。","grammar:3234:ex2:words:0:zh":"he","grammar:3234:ex2:words:0:note":"かれ","grammar:3234:ex2:words:0:pos":"pronoun","grammar:3234:ex2:words:1:zh":"(topic marker)","grammar:3234:ex2:words:1:pos":"particle","grammar:3234:ex2:words:2:zh":"Switzerland","grammar:3234:ex2:words:2:note":"loanword","grammar:3234:ex2:words:2:pos":"noun","grammar:3234:ex2:words:3:zh":"(place of residence)","grammar:3234:ex2:words:3:pos":"particle","grammar:3234:ex2:words:4:zh":"living","grammar:3234:ex2:words:4:note":"〜ている expresses a state","grammar:3234:ex2:words:4:pos":"verb","grammar:3234:ex2:points:0":"〜に住んでいる: to live in …","grammar:3234:ex2:points:1":"スイス: Switzerland","grammar:3234:ex3:trans":"I love Swiss chocolate.","grammar:3234:ex3:structure":"〔スイスチョコレート〕＋が＋大好きです。 「大好き」 = to love …","grammar:3234:ex3:words:0:zh":"Switzerland","grammar:3234:ex3:words:0:note":"loanword","grammar:3234:ex3:words:0:pos":"noun","grammar:3234:ex3:words:1:zh":"chocolate","grammar:3234:ex3:words:1:note":"loanword","grammar:3234:ex3:words:1:pos":"noun","grammar:3234:ex3:words:2:zh":"(object marker)","grammar:3234:ex3:words:2:pos":"particle","grammar:3234:ex3:words:3:zh":"love","grammar:3234:ex3:words:3:note":"だいすき","grammar:3234:ex3:words:3:pos":"na-adjective","grammar:3234:ex3:words:4:zh":"(polite form)","grammar:3234:ex3:words:4:pos":"copula","grammar:3234:ex3:points:0":"〜が大好きです: to love …","grammar:3234:ex3:points:1":"スイスチョコレート: Swiss chocolate","grammar:3234:ex4:trans":"Switzerland is a neutral country.","grammar:3234:ex4:structure":"nounは＋nounです.","grammar:3234:ex4:words:0:zh":"Switzerland","grammar:3234:ex4:words:0:note":"loanword","grammar:3234:ex4:words:0:pos":"noun","grammar:3234:ex4:words:1:zh":"(topic marker)","grammar:3234:ex4:words:1:pos":"particle","grammar:3234:ex4:words:2:zh":"neutral country","grammar:3234:ex4:words:2:note":"ちゅうりつこく","grammar:3234:ex4:words:2:pos":"noun","grammar:3234:ex4:words:3:zh":"is","grammar:3234:ex4:words:3:pos":"copula","grammar:3234:ex4:points:0":"中立国: neutral country","grammar:3234:ex4:points:1":"AはB です","grammar:3234:ex5:trans":"Switzerland is famous for its snowy mountains.","grammar:3234:ex5:structure":"〜は＋noun＋が＋な-adjectiveです。「〜は〜が有名」＝(a place) is famous for ….","grammar:3234:ex5:words:0:zh":"Switzerland","grammar:3234:ex5:words:0:note":"loanword","grammar:3234:ex5:words:0:pos":"noun","grammar:3234:ex5:words:1:zh":"(topic marker)","grammar:3234:ex5:words:1:pos":"particle","grammar:3234:ex5:words:2:zh":"snowy mountains","grammar:3234:ex5:words:2:note":"ゆきやま","grammar:3234:ex5:words:2:pos":"noun","grammar:3234:ex5:words:3:zh":"(nominative)","grammar:3234:ex5:words:3:pos":"particle","grammar:3234:ex5:words:4:zh":"famous","grammar:3234:ex5:words:4:note":"ゆうめい","grammar:3234:ex5:words:4:pos":"na-adjective","grammar:3234:ex5:words:5:zh":"(polite form)","grammar:3234:ex5:words:5:pos":"copula","grammar:3234:ex5:points:0":"〜は〜が有名です: to be famous for …","grammar:3234:ex5:points:1":"雪山: snowy mountain"},"3236":{"example:3236:exzh":"Whistler is famous for winter sports.","example:3236:exzh2":"I went to a ski resort in Whistler.","example:3236:exzh3":"Whistler is popular with tourists.","example:3236:exzh4":"The mountains of Whistler are beautiful.","example:3236:exzh5":"There are lots of activities in Whistler."},"3237":{"example:3237:exzh":"This is my book.","example:3237:exzh2":"This is a picture my little brother drew.","example:3237:exzh3":"You're a student.","example:3237:exzh4":"The weather is nice today.","example:3237:exzh5":"This is special.","grammar:3237:ex:trans":"This is my book.","grammar:3237:ex:structure":"これ＋が＋〔名詞の名詞〕＋だ。 「だ」 is the plain-form copula (= the plain form of です).","grammar:3237:ex:explain":"This sentence shows the plain-form copula 「だ」. 「だ」 is the plain/colloquial form of 「です」, used where politeness isn't needed; 「これが私の本だ」 = \"This is my book.\" Here the subject takes 「が」 rather than 「は」, which adds an emphatic, exclusive feel—\"this one, not another\"—common when identifying something or answering \"which one is it?\"; 「私の本」 uses 「の」 for possession. If you changed it to 「これは私の本だ」, the tone would shift from \"this is the one\" to a simple introduction—\"this one? it's my book\"—a single particle changes the nuance.","grammar:3237:ex:words:0:zh":"this","grammar:3237:ex:words:0:pos":"pronoun","grammar:3237:ex:words:1:zh":"(nominative)","grammar:3237:ex:words:1:note":"emphasizes \"this one, specifically\"","grammar:3237:ex:words:1:pos":"particle","grammar:3237:ex:words:2:zh":"I","grammar:3237:ex:words:2:note":"わたし","grammar:3237:ex:words:2:pos":"pronoun","grammar:3237:ex:words:3:zh":"'s","grammar:3237:ex:words:3:pos":"particle","grammar:3237:ex:words:4:zh":"book","grammar:3237:ex:words:4:note":"ほん","grammar:3237:ex:words:4:pos":"noun","grammar:3237:ex:words:5:zh":"is","grammar:3237:ex:words:5:note":"plain-form copula, the plain form of です","grammar:3237:ex:words:5:pos":"copula","grammar:3237:ex:points:0":"だ: plain-form copula \"is\" (= the plain/colloquial form of です)","grammar:3237:ex:points:1":"が: emphasizes the subject (this one, not another)","grammar:3237:ex2:trans":"This is a picture my little brother drew.","grammar:3237:ex2:structure":"これは＋弟が描いた絵＋だ","grammar:3237:ex2:words:0:zh":"this","grammar:3237:ex2:words:0:pos":"pronoun","grammar:3237:ex2:words:1:zh":"topic marker","grammar:3237:ex2:words:1:pos":"particle","grammar:3237:ex2:words:2:zh":"younger brother","grammar:3237:ex2:words:2:note":"おとうと; little brother","grammar:3237:ex2:words:2:pos":"noun","grammar:3237:ex2:words:3:zh":"the subject inside the modifying clause","grammar:3237:ex2:words:3:pos":"particle","grammar:3237:ex2:words:4:zh":"picture","grammar:3237:ex2:words:4:note":"かい; the ta-form stem of 描く","grammar:3237:ex2:words:4:pos":"verb","grammar:3237:ex2:words:5:zh":"the past","grammar:3237:ex2:words:5:pos":"auxiliary verb","grammar:3237:ex2:words:6:zh":"picture","grammar:3237:ex2:words:6:note":"え; picture","grammar:3237:ex2:words:6:pos":"noun","grammar:3237:ex2:words:7:zh":"is","grammar:3237:ex2:words:7:pos":"copula","grammar:3237:ex2:points:0":"The 「だ」 at the end of 「絵だ」 is the plain form of 「です」, used when saying \"this is …\" among friends or family.","grammar:3237:ex2:points:1":"The whole 「弟が描いた」 modifies 「絵」, saying who drew the picture; the subject inside the clause takes 「が」.","grammar:3237:ex3:trans":"You're a student.","grammar:3237:ex3:structure":"Noun は＋noun＋だ. “だ” is the plain-form copula in a noun sentence.","grammar:3237:ex3:words:0:zh":"you","grammar:3237:ex3:words:0:note":"きみ","grammar:3237:ex3:words:0:pos":"pronoun","grammar:3237:ex3:words:1:zh":"(topic marker)","grammar:3237:ex3:words:1:pos":"particle","grammar:3237:ex3:words:2:zh":"student","grammar:3237:ex3:words:2:note":"がくせい","grammar:3237:ex3:words:2:pos":"noun","grammar:3237:ex3:words:3:zh":"is","grammar:3237:ex3:words:3:note":"plain-form copula","grammar:3237:ex3:words:3:pos":"copula","grammar:3237:ex3:points:0":"noun＋だ: plain \"is …\" (the polite form is です)","grammar:3237:ex3:points:1":"君: you (fairly casual)","grammar:3237:ex4:trans":"The weather is nice today.","grammar:3237:ex4:structure":"名詞は＋〔いい天気〕＋だ。 A noun predicate ends in だ (plain form).","grammar:3237:ex4:words:0:zh":"today","grammar:3237:ex4:words:0:note":"きょう","grammar:3237:ex4:words:0:pos":"noun","grammar:3237:ex4:words:1:zh":"(topic marker)","grammar:3237:ex4:words:1:pos":"particle","grammar:3237:ex4:words:2:zh":"good","grammar:3237:ex4:words:2:pos":"adjective","grammar:3237:ex4:words:3:zh":"weather","grammar:3237:ex4:words:3:note":"てんき","grammar:3237:ex4:words:3:pos":"noun","grammar:3237:ex4:words:4:zh":"is","grammar:3237:ex4:words:4:note":"plain-form copula","grammar:3237:ex4:words:4:pos":"copula","grammar:3237:ex4:points:0":"いい天気だ: (it's) nice weather (plain form)","grammar:3237:ex4:points:1":"i-adjective＋noun＋だ","grammar:3237:ex5:trans":"This is special.","grammar:3237:ex5:structure":"これ＋は＋な形容詞＋だ。 「な形容詞＋だ」 is the plain form (the polite form is です).","grammar:3237:ex5:words:0:zh":"this","grammar:3237:ex5:words:0:pos":"pronoun","grammar:3237:ex5:words:1:zh":"(topic marker)","grammar:3237:ex5:words:1:pos":"particle","grammar:3237:ex5:words:2:zh":"special","grammar:3237:ex5:words:2:note":"とくべつ","grammar:3237:ex5:words:2:pos":"na-adjective","grammar:3237:ex5:words:3:zh":"is","grammar:3237:ex5:words:3:note":"plain-form copula with a na-adjective","grammar:3237:ex5:words:3:pos":"copula","grammar:3237:ex5:points:0":"na-adjective＋だ: plain-form copula (特別だ = is special)","grammar:3237:ex5:points:1":"だ corresponds to the polite です","exam:3237:zh":"On the robot's screen, the phrase \"this is a pen\" is written in katakana.","exam:3237:why":"「ダ」 corresponds to the plain-form 「だ」, placed after a noun to make an affirmative statement. 「デ」 corresponds to 「で」, and can't end this affirmative sentence on its own here."},"3238":{"example:3238:exzh":"There's a legend that a monster lives in this village.","example:3238:exzh2":"The children say they're scared of monsters.","example:3238:exzh3":"The monster in the movie looked very real.","example:3238:exzh4":"Have you ever seen a monster?","example:3238:exzh5":"There are many kinds of monsters in Japan."},"3239":{"example:3239:exzh":"He is working on this project with passion.","example:3239:exzh2":"You won't succeed without passion.","example:3239:exzh3":"Her passion inspires the people around her.","example:3239:exzh4":"It's important to keep your passion alive.","example:3239:exzh5":"His passion produced results."},"3240":{"example:3240:exzh":"It takes effort to gain glory.","example:3240:exzh2":"Don't miss his moment of glory.","example:3240:exzh3":"Glory is fleeting.","example:3240:exzh4":"The whole team shared in the glory.","example:3240:exzh5":"Gaining glory and fame isn't easy."},"3241":{"example:3241:exzh":"He said he wants his private life respected.","example:3241:exzh2":"In private, he's a very fun person.","example:3241:exzh3":"I need some private time.","example:3241:exzh4":"I don't want to talk about my private life.","example:3241:exzh5":"You should keep your private life and work separate."},"3242":{"example:3242:exzh":"It was cold, so I bought two pairs of gloves.","example:3242:exzh2":"He has a baseball glove.","example:3242:exzh3":"I want a new pair of gloves.","example:3242:exzh4":"You can't do without gloves in winter.","example:3242:exzh5":"These gloves are warm."},"3245":{"example:3245:exzh":"You can watch a movie for free today.","example:3245:exzh2":"If there's something free, I'd love to have it.","example:3245:exzh3":"This event is free.","example:3245:exzh4":"I got some snacks for free.","example:3245:exzh5":"Free stuff is the best."},"3246":{"example:3246:exzh":"I heard a gunshot in the distance.","example:3246:exzh2":"During the war, the gunfire never stopped.","example:3246:exzh3":"When the gunshot rang out, everyone ran.","example:3246:exzh4":"He woke up startled by the gunshot.","example:3246:exzh5":"Hearing a gunshot makes me scared."},"3247":{"example:3247:exzh":"He might be a bit of a pervert.","example:3247:exzh2":"Perversion is part of subculture.","example:3247:exzh3":"That movie has a lot of perverted elements.","example:3247:exzh4":"The word 「変態」 is often misunderstood.","example:3247:exzh5":"My friend is good at drawing perverted pictures."},"3248":{"example:3248:exzh":"I sweated after exercising.","example:3248:exzh2":"On hot days, I can't stop sweating.","example:3248:exzh3":"He sweats when he gets nervous.","example:3248:exzh4":"Sweating makes your body feel lighter.","example:3248:exzh5":"Once summer comes, I sweat a lot more.","grammar:3248:ex:trans":"After I exercised, I broke a sweat.","grammar:3248:ex:structure":"〔運動をしたら〕、汗を＋かいた。「〜たら」 marks a condition or trigger, 「汗をかく」＝ to sweat. 「汗」＝ sweat.","grammar:3248:ex:explain":"There are two key points here. The first is 「〜たら」, a conditional / trigger form that attaches to a verb's ta-form and means after … (then something happened): 「運動をしたら」＝ after exercising. The second is the set phrase 「汗をかく」＝ to sweat; 「汗」 is marked with 「を」 and 「かく」 is the verb used specifically for breaking a sweat, here in the past form 「かいた」. The whole sentence 「運動をしたら汗をかいた」＝ after exercising, I broke a sweat. Remember that Japanese does not use 「出る」 for sweating but the fixed collocation 「汗をかく」.","grammar:3248:ex:words:0:zh":"exercise","grammar:3248:ex:words:0:note":"うんどう","grammar:3248:ex:words:0:pos":"noun","grammar:3248:ex:words:1:zh":"(object marker)","grammar:3248:ex:words:1:pos":"particle","grammar:3248:ex:words:2:zh":"after doing","grammar:3248:ex:words:2:note":"ta-form＋ら (conditional)","grammar:3248:ex:words:2:pos":"verb","grammar:3248:ex:words:3:zh":"sweat","grammar:3248:ex:words:3:note":"あせ","grammar:3248:ex:words:3:pos":"noun","grammar:3248:ex:words:4:zh":"(object marker)","grammar:3248:ex:words:4:pos":"particle","grammar:3248:ex:words:5:zh":"break (a sweat)","grammar:3248:ex:words:5:note":"かいた","grammar:3248:ex:words:5:pos":"verb","grammar:3248:ex:points:0":"汗（あせ）: sweat","grammar:3248:ex:points:1":"汗をかく: to sweat / 〜たら: after …","grammar:3248:ex2:trans":"On hot days the sweat won't stop.","grammar:3248:ex2:structure":"〔暑い日〕＋には、汗が＋止まらない。「〜には」 emphasizes the time, 「汗が止まらない」＝ the sweat won't stop.","grammar:3248:ex2:words:0:zh":"hot","grammar:3248:ex2:words:0:note":"あつい","grammar:3248:ex2:words:0:pos":"adjective","grammar:3248:ex2:words:1:zh":"day","grammar:3248:ex2:words:1:note":"ひ","grammar:3248:ex2:words:1:pos":"noun","grammar:3248:ex2:words:2:zh":"(time + emphasis)","grammar:3248:ex2:words:2:pos":"particle","grammar:3248:ex2:words:3:zh":"sweat","grammar:3248:ex2:words:3:note":"あせ","grammar:3248:ex2:words:3:pos":"noun","grammar:3248:ex2:words:4:zh":"(nominative)","grammar:3248:ex2:words:4:pos":"particle","grammar:3248:ex2:words:5:zh":"wouldn't stop","grammar:3248:ex2:words:5:note":"negative","grammar:3248:ex2:words:5:pos":"verb","grammar:3248:ex2:points:0":"暑い日: a hot day","grammar:3248:ex2:points:1":"汗が止まらない: the sweat won't stop","grammar:3248:ex3:trans":"When he gets nervous, he sweats.","grammar:3248:ex3:structure":"〜は＋〔緊張する＋と〕、汗を＋かく。「と」 marks a natural consequence.","grammar:3248:ex3:words:0:zh":"he","grammar:3248:ex3:words:0:note":"かれ","grammar:3248:ex3:words:0:pos":"pronoun","grammar:3248:ex3:words:1:zh":"(topic marker)","grammar:3248:ex3:words:1:pos":"particle","grammar:3248:ex3:words:2:zh":"tense","grammar:3248:ex3:words:2:note":"dictionary form","grammar:3248:ex3:words:2:pos":"verb","grammar:3248:ex3:words:3:zh":"(as soon as…)","grammar:3248:ex3:words:3:pos":"particle","grammar:3248:ex3:words:4:zh":"sweat","grammar:3248:ex3:words:4:note":"あせ","grammar:3248:ex3:words:4:pos":"noun","grammar:3248:ex3:words:5:zh":"(object marker)","grammar:3248:ex3:words:5:pos":"particle","grammar:3248:ex3:words:6:zh":"break (a sweat)","grammar:3248:ex3:words:6:note":"dictionary form","grammar:3248:ex3:words:6:pos":"verb","grammar:3248:ex3:points:0":"〜と: when …, then … (緊張すると = when nervous)","grammar:3248:ex3:points:1":"汗をかく: to sweat","grammar:3248:ex4:trans":"Sweating makes your body feel lighter.","grammar:3248:ex4:structure":"〔汗をかく＋と〕、体が＋軽くなる。「と」 marks a natural consequence, 「軽くなる」＝ to become lighter.","grammar:3248:ex4:words:0:zh":"sweat","grammar:3248:ex4:words:0:note":"あせ","grammar:3248:ex4:words:0:pos":"noun","grammar:3248:ex4:words:1:zh":"(object marker)","grammar:3248:ex4:words:1:pos":"particle","grammar:3248:ex4:words:2:zh":"break (a sweat)","grammar:3248:ex4:words:2:note":"dictionary form","grammar:3248:ex4:words:2:pos":"verb","grammar:3248:ex4:words:3:zh":"(as soon as…)","grammar:3248:ex4:words:3:pos":"particle","grammar:3248:ex4:words:4:zh":"body","grammar:3248:ex4:words:4:note":"からだ","grammar:3248:ex4:words:4:pos":"noun","grammar:3248:ex4:words:5:zh":"(nominative)","grammar:3248:ex4:words:5:pos":"particle","grammar:3248:ex4:words:6:zh":"become lighter","grammar:3248:ex4:words:6:note":"〜くなる","grammar:3248:ex4:words:6:pos":"adjective","grammar:3248:ex4:points:0":"〜と: when …, then … (かくと = once you sweat)","grammar:3248:ex4:points:1":"軽くなる: to become lighter (軽い + くなる)","grammar:3248:ex5:trans":"Once summer arrives, you sweat a lot more.","grammar:3248:ex5:structure":"〔夏になる＋と〕、汗が＋多くなります。「〜になると」＝ once it becomes …, 「多くなる」＝ to increase.","grammar:3248:ex5:words:0:zh":"summer","grammar:3248:ex5:words:0:note":"なつ","grammar:3248:ex5:words:0:pos":"noun","grammar:3248:ex5:words:1:zh":"(result of the change)","grammar:3248:ex5:words:1:pos":"particle","grammar:3248:ex5:words:2:zh":"until","grammar:3248:ex5:words:2:note":"dictionary form","grammar:3248:ex5:words:2:pos":"verb","grammar:3248:ex5:words:3:zh":"(as soon as…)","grammar:3248:ex5:words:3:pos":"particle","grammar:3248:ex5:words:4:zh":"sweat","grammar:3248:ex5:words:4:note":"あせ","grammar:3248:ex5:words:4:pos":"noun","grammar:3248:ex5:words:5:zh":"(nominative)","grammar:3248:ex5:words:5:pos":"particle","grammar:3248:ex5:words:6:zh":"become more","grammar:3248:ex5:words:6:note":"〜くなる","grammar:3248:ex5:words:6:pos":"adjective","grammar:3248:ex5:points:0":"〜になると：once it becomes …（夏になると＝once summer comes）","grammar:3248:ex5:points:1":"多くなる: to increase"},"3249":{"example:3249:exzh":"This country has an ancient civilization.","example:3249:exzh2":"The evolution of civilization is an interesting topic.","example:3249:exzh3":"They are trying to build a new civilization.","example:3249:exzh4":"Civilization is closely tied to culture.","example:3249:exzh5":"Modern civilization is developing rapidly."},"3250":{"example:3250:exzh":"Everything he says is nonsense.","example:3250:exzh2":"This is no time for nonsense.","example:3250:exzh3":"That opinion is complete nonsense.","example:3250:exzh4":"You're better off not dwelling on that nonsense.","example:3250:exzh5":"She likes talking nonsense."},"3251":{"example:3251:exzh":"He holds a grudge.","example:3251:exzh2":"Letting go of a grudge is hard.","example:3251:exzh3":"You're better off not holding a grudge.","example:3251:exzh4":"A grudge torments the heart.","example:3251:exzh5":"She can't forget her grudge."},"3252":{"example:3252:exzh":"The crime of forgery is serious.","example:3252:exzh2":"He committed forgery.","example:3252:exzh3":"Counterfeits are hard to tell apart.","example:3252:exzh4":"This document is a forgery.","example:3252:exzh5":"You need to be careful to prevent forgery."},"3253":{"example:3253:exzh":"He taught me magic tricks.","example:3253:exzh2":"I used a magic trick to surprise my friend.","example:3253:exzh3":"I went to see a magic show.","example:3253:exzh4":"This magic trick is easy.","example:3253:exzh5":"I bought some magic props."},"3254":{"example:3254:exzh":"Please refer to the materials.","example:3254:exzh2":"He is referring to a book.","example:3254:exzh3":"Let's check the references.","example:3254:exzh4":"This reference is important.","example:3254:exzh5":"We need to refer to that data."},"3255":{"example:3255:exzh":"He has held the world record for three years.","example:3255:exzh2":"Personal information is kept safe.","example:3255:exzh3":"We're working hard to maintain good relations.","example:3255:exzh4":"I exercise to maintain my health.","example:3255:exzh5":"To keep this qualification, it must be renewed every three years."},"3256":{"example:3256:exzh":"She works as a secretary.","example:3256:exzh2":"A new secretary was hired.","example:3256:exzh3":"The secretary is preparing for the meeting.","example:3256:exzh4":"I talked with the secretary.","example:3256:exzh5":"He is a good secretary."},"3257":{"example:3257:exzh":"Setting an ambush is dangerous.","example:3257:exzh2":"He lay in ambush at that spot.","example:3257:exzh3":"The ambush plan succeeded.","example:3257:exzh4":"I didn't notice that I was being ambushed.","example:3257:exzh5":"My friend is lying in ambush."},"3258":{"example:3258:exzh":"I like the lines in that movie.","example:3258:exzh2":"He is practicing his lines.","example:3258:exzh3":"The lines left a strong impression.","example:3258:exzh4":"This line is famous.","example:3258:exzh5":"Her lines are wonderful."},"3260":{"example:3260:exzh":"Pull the rope tight.","example:3260:exzh2":"I'll stretch it using this force.","example:3260:exzh3":"Please stick this picture on the wall.","example:3260:exzh4":"His face was tense.","example:3260:exzh5":"They are pitching a tent in the yard."},"3261":{"example:3261:exzh":"He is good at guiding children.","example:3261:exzh2":"Proper guidance is necessary.","example:3261:exzh3":"I'll learn guidance techniques.","example:3261:exzh4":"This manual is helpful for guidance.","example:3261:exzh5":"I've been put in charge of guiding the new employees."},"3262":{"example:3262:exzh":"This inn was very clean.","example:3262:exzh2":"I'm looking forward to staying at the inn.","example:3262:exzh3":"We went to an inn in the mountains.","example:3262:exzh4":"The food at the inn was delicious.","example:3262:exzh5":"We relaxed at a simple inn."},"3264":{"example:3264:exzh":"He often looks back on the past.","example:3264:exzh2":"Looking back, there are many memories.","example:3264:exzh3":"Looking back makes me feel nostalgic.","example:3264:exzh4":"I set aside time for reflection every year.","example:3264:exzh5":"We grow by looking back."},"3265":{"example:3265:exzh":"She is interested in the media.","example:3265:exzh2":"The media have a big influence.","example:3265:exzh3":"New forms of media keep appearing one after another.","example:3265:exzh4":"Information is conveyed through the media.","example:3265:exzh5":"I work in the media industry."},"3266":{"example:3266:exzh":"He threw the ball at the wall.","example:3266:exzh2":"Please be careful not to bump into anything.","example:3266:exzh3":"The car was hit.","example:3266:exzh4":"I bumped my head.","example:3266:exzh5":"After the collision, he looked a little surprised."},"3267":{"example:3267:exzh":"A fish's gills help it breathe.","example:3267:exzh2":"She says her gills hurt.","example:3267:exzh3":"The structure of gills is very interesting.","example:3267:exzh4":"Let's take good care of our gills.","example:3267:exzh5":"I'm interested in creatures that have gills."},"3268":{"example:3268:exzh":"That result was unexpected.","example:3268:exzh2":"His remark had something surprising about it.","example:3268:exzh3":"Unexpectedly, she won.","example:3268:exzh4":"It was a surprisingly easy question.","example:3268:exzh5":"This movie was surprisingly interesting."},"3269":{"example:3269:exzh":"This is treated as an exception.","example:3269:exzh2":"There are cases where there are exceptions.","example:3269:exzh3":"Exceptions exist in rules.","example:3269:exzh4":"He has exceptional talent.","example:3269:exzh5":"The exceptions are as follows."},"3270":{"example:3270:exzh":"Because he did something nice for her, he expects something in return.","example:3270:exzh2":"It's important to help others without expecting anything in return.","example:3270:exzh3":"Sometimes people demand something in return even from animals.","example:3270:exzh4":"Without something in return, trust is never born.","example:3270:exzh5":"The ideal friendship is one that asks for nothing in return."},"3271":{"example:3271:exzh":"The police questioned people about the case.","example:3271:exzh2":"As a result of the questioning, it turned out he was innocent.","example:3271:exzh3":"She was called in for questioning.","example:3271:exzh4":"Questioning needs to be carried out carefully.","example:3271:exzh5":"After the questioning ended, he went home."},"3272":{"example:3272:exzh":"Traces were left at the scene.","example:3272:exzh2":"From these traces, you can tell who came.","example:3272:exzh3":"They investigated the case by following the traces.","example:3272:exzh4":"We need to push the investigation forward before the culprit's traces disappear.","example:3272:exzh5":"Traces can become important evidence."},"3273":{"example:3273:exzh":"The probability of solving this case is extremely low.","example:3273:exzh2":"The odds of winning the lottery are very small.","example:3273:exzh3":"You should act after considering the probability.","example:3273:exzh4":"The scientists used data to calculate the probability.","example:3273:exzh5":"The odds of winning this game are one in five."},"3274":{"example:3274:exzh":"There are lots of ants in the yard.","example:3274:exzh2":"Ants have a special society.","example:3274:exzh3":"Ants are very hard workers.","example:3274:exzh4":"I found an anthill.","example:3274:exzh5":"This ant is carrying food."},"3275":{"example:3275:exzh":"He updates his blog every day.","example:3275:exzh2":"This blog is full of interesting information.","example:3275:exzh3":"Writing a blog is my hobby.","example:3275:exzh4":"Many people have their own blogs.","example:3275:exzh5":"I made friends through my blog."},"3276":{"example:3276:exzh":"A new minister took office.","example:3276:exzh2":"The minister decides the country's policies.","example:3276:exzh3":"That minister is very popular.","example:3276:exzh4":"The minister will attend the meeting.","example:3276:exzh5":"He works as the environment minister."},"3277":{"example:3277:exzh":"The internet connection is unstable.","example:3277:exzh2":"The phone line won't connect.","example:3277:exzh3":"I signed up for a new line.","example:3277:exzh4":"Please let me know if the line goes down.","example:3277:exzh5":"It's a big help that the connection speed is fast."},"3278":{"example:3278:exzh":"I put the book on the shelf.","example:3278:exzh2":"This shelf is very sturdy.","example:3278:exzh3":"I need to tidy up the shelf.","example:3278:exzh4":"I want to buy a new shelf.","example:3278:exzh5":"I displayed a photo on the shelf.","grammar:3278:ex:trans":"I put the book on the shelf.","grammar:3278:ex:structure":"noun に＋noun を＋置いた. 「〜に置く」 = to put on/in…","grammar:3278:ex:explain":"The key here is 「〜に置く」 = \"to put on/in…\". 「置く」 is the transitive verb \"to place\"; the place where the thing ends up is marked with 「に」, so 「棚に」 = \"on the shelf\". The thing being placed, 「本」 (book), is marked with 「を」, and the past tense is 「置いた」. The whole sentence 「棚に本を置いた」 = \"I put the book on the shelf.\" Note that the destination of \"putting something somewhere\" takes 「に」 (the ending point); this differs from 「で」, which marks where an action takes place — the destination of placing emphasizes the final location of the thing.","grammar:3278:ex:words:0:zh":"shelf","grammar:3278:ex:words:0:note":"たな","grammar:3278:ex:words:0:pos":"noun","grammar:3278:ex:words:1:zh":"(the destination)","grammar:3278:ex:words:1:pos":"particle","grammar:3278:ex:words:2:zh":"book","grammar:3278:ex:words:2:note":"ほん","grammar:3278:ex:words:2:pos":"noun","grammar:3278:ex:words:3:zh":"(object marker)","grammar:3278:ex:words:3:pos":"particle","grammar:3278:ex:words:4:zh":"put (past)","grammar:3278:ex:words:4:note":"おいた; ta-form","grammar:3278:ex:words:4:pos":"verb","grammar:3278:ex:points:0":"〜に置く: to put on/in…","grammar:3278:ex:points:1":"棚: shelf","grammar:3278:ex2:trans":"This shelf is very sturdy.","grammar:3278:ex2:structure":"この＋noun＋は＋とても＋na-adjective＋です.","grammar:3278:ex2:words:0:zh":"this","grammar:3278:ex2:words:0:pos":"pre-noun adjectival","grammar:3278:ex2:words:1:zh":"shelf","grammar:3278:ex2:words:1:note":"たな","grammar:3278:ex2:words:1:pos":"noun","grammar:3278:ex2:words:2:zh":"(topic marker)","grammar:3278:ex2:words:2:pos":"particle","grammar:3278:ex2:words:3:zh":"extremely","grammar:3278:ex2:words:3:pos":"adverb","grammar:3278:ex2:words:4:zh":"sturdy","grammar:3278:ex2:words:4:note":"がんじょう","grammar:3278:ex2:words:4:pos":"na-adjective","grammar:3278:ex2:words:5:zh":"(polite form)","grammar:3278:ex2:words:5:pos":"copula","grammar:3278:ex2:points:0":"頑丈: sturdy, solid (na-adjective)","grammar:3278:ex2:points:1":"とても頑丈: very sturdy","grammar:3278:ex3:trans":"I need to tidy up the shelf.","grammar:3278:ex3:structure":"nounを＋〔dictionary-form verb〕＋必要があります.","grammar:3278:ex3:words:0:zh":"shelf","grammar:3278:ex3:words:0:note":"たな","grammar:3278:ex3:words:0:pos":"noun","grammar:3278:ex3:words:1:zh":"(object marker)","grammar:3278:ex3:words:1:pos":"particle","grammar:3278:ex3:words:2:zh":"organize","grammar:3278:ex3:words:2:note":"せいりする; dictionary form","grammar:3278:ex3:words:2:pos":"verb","grammar:3278:ex3:words:3:zh":"necessary","grammar:3278:ex3:words:3:note":"ひつよう","grammar:3278:ex3:words:3:pos":"na-adjective","grammar:3278:ex3:words:4:zh":"(nominative)","grammar:3278:ex3:words:4:pos":"particle","grammar:3278:ex3:words:5:zh":"there is / are","grammar:3278:ex3:words:5:note":"〜必要がある","grammar:3278:ex3:words:5:pos":"verb","grammar:3278:ex3:points:0":"〜必要がある: need to …","grammar:3278:ex3:points:1":"整理する: to tidy up","grammar:3278:ex4:trans":"I want to buy a new shelf.","grammar:3278:ex4:structure":"i-adjective＋noun＋を＋verb たい. 「〜たい」 expresses a wish.","grammar:3278:ex4:words:0:zh":"new","grammar:3278:ex4:words:0:note":"あたらしい","grammar:3278:ex4:words:0:pos":"adjective","grammar:3278:ex4:words:1:zh":"shelf","grammar:3278:ex4:words:1:note":"たな","grammar:3278:ex4:words:1:pos":"noun","grammar:3278:ex4:words:2:zh":"(object marker)","grammar:3278:ex4:words:2:pos":"particle","grammar:3278:ex4:words:3:zh":"want to buy","grammar:3278:ex4:words:3:note":"かいたい; 〜たい expresses a wish","grammar:3278:ex4:words:3:pos":"verb","grammar:3278:ex4:points:0":"〜たい: want to …","grammar:3278:ex4:points:1":"新しい棚: a new shelf","grammar:3278:ex5:trans":"I displayed a photo on the shelf.","grammar:3278:ex5:structure":"noun に＋noun を＋飾りました. 「〜に飾る」 = to display or decorate on…","grammar:3278:ex5:words:0:zh":"shelf","grammar:3278:ex5:words:0:note":"たな","grammar:3278:ex5:words:0:pos":"noun","grammar:3278:ex5:words:1:zh":"(the destination)","grammar:3278:ex5:words:1:pos":"particle","grammar:3278:ex5:words:2:zh":"photo","grammar:3278:ex5:words:2:note":"しゃしん","grammar:3278:ex5:words:2:pos":"noun","grammar:3278:ex5:words:3:zh":"(object marker)","grammar:3278:ex5:words:3:pos":"particle","grammar:3278:ex5:words:4:zh":"decorated / displayed","grammar:3278:ex5:words:4:note":"かざりました","grammar:3278:ex5:words:4:pos":"verb","grammar:3278:ex5:points:0":"飾る: to decorate, to display","grammar:3278:ex5:points:1":"棚に飾る: to display on the shelf"},"3279":{"example:3279:exzh":"The cable broke.","example:3279:exzh2":"This cable is very convenient.","example:3279:exzh3":"Please connect the cable.","example:3279:exzh4":"I need to buy a new cable.","example:3279:exzh5":"The TV cable broke."},"3280":{"example:3280:exzh":"He scared her by using threats.","example:3280:exzh2":"Threatening is not allowed.","example:3280:exzh3":"If you receive a threat, report it immediately.","example:3280:exzh4":"Controlling someone through threats is wrong.","example:3280:exzh5":"Threatening people won't solve anything."},"3281":{"example:3281:exzh":"He seems to be hiding something.","example:3281:exzh2":"It's hard to find what someone is hiding.","example:3281:exzh3":"Keeping secrets hidden builds up stress.","example:3281:exzh4":"I need to bring this hidden matter to light.","example:3281:exzh5":"Living while hiding something is hard."},"3282":{"example:3282:exzh":"A password is required to enter this site.","example:3282:exzh2":"If you forget your password, you can reset it.","example:3282:exzh3":"Please don't tell anyone else your password.","example:3282:exzh4":"It's important to create a secure password.","example:3282:exzh5":"You should avoid simple passwords."},"3283":{"example:3283:exzh":"I gave a present to my friend.","example:3283:exzh2":"I'm planning to give her flowers for her birthday.","example:3283:exzh3":"I'll send a letter to express my gratitude.","example:3283:exzh4":"I like giving toys to kids.","example:3283:exzh5":"I want to give something for a special day."},"3284":{"example:3284:exzh":"He likes babies.","example:3284:exzh2":"I bought baby clothes.","example:3284:exzh3":"She is holding a baby.","example:3284:exzh4":"I'm planning to hire a babysitter.","example:3284:exzh5":"I'll use a stroller to go to the park."},"3285":{"example:3285:exzh":"A new edition has been published.","example:3285:exzh2":"This edition is very popular.","example:3285:exzh3":"I'm collecting old editions of books.","example:3285:exzh4":"I got the latest version of the game.","example:3285:exzh5":"This movie is different from the first version."},"3286":{"example:3286:exzh":"A rocket was launched into space.","example:3286:exzh2":"The kids made a model rocket.","example:3286:exzh3":"I want to learn about rocket technology.","example:3286:exzh4":"He's interested in rockets.","example:3286:exzh5":"The next rocket launch is next month."},"3287":{"example:3287:exzh":"There's a meeting on Thursday.","example:3287:exzh2":"I'm planning to meet a friend on Thursday.","example:3287:exzh3":"I'll finish my homework on Thursday.","example:3287:exzh4":"What are you doing Thursday night?","example:3287:exzh5":"Thursday is a special day.","grammar:3287:ex:trans":"There's a meeting on Thursday.","grammar:3287:ex:structure":"timeは＋nounが＋あります. 「〜がある」 expresses that an event exists / is held.","grammar:3287:ex:explain":"The point of this sentence is the existential pattern 「〜がある」, which expresses that an event or activity exists. 「会議がある」＝there is a meeting, with 「会議」 marked by 「が」. The time topic 「木曜日は」 uses 「は」 to present it as for Thursday, which adds a slight nuance of contrast or topicalization. The whole sentence 「木曜日は会議があります」＝there is a meeting on Thursday. Note that 「ある」 is used for the existence of inanimate things and events; when you want to say what is scheduled or happening at a certain time, use the frame （time）は＋（event）が＋ある.","grammar:3287:ex:words:0:zh":"Thursday","grammar:3287:ex:words:0:note":"もくようび","grammar:3287:ex:words:0:pos":"noun","grammar:3287:ex:words:1:zh":"(topic marker)","grammar:3287:ex:words:1:pos":"particle","grammar:3287:ex:words:2:zh":"meeting","grammar:3287:ex:words:2:note":"かいぎ","grammar:3287:ex:words:2:pos":"noun","grammar:3287:ex:words:3:zh":"(nominative)","grammar:3287:ex:words:3:pos":"particle","grammar:3287:ex:words:4:zh":"there is / are","grammar:3287:ex:words:4:note":"exists / there is","grammar:3287:ex:words:4:pos":"verb","grammar:3287:ex:points:0":"〜がある：there is (an event / a meeting)","grammar:3287:ex:points:1":"木曜日：Thursday","grammar:3287:ex2:trans":"I'm planning to meet a friend on Thursday.","grammar:3287:ex2:structure":"timeに＋nounと＋〔verb dictionary form＋つもり〕＋です. 「〜と会う」＝to meet with…","grammar:3287:ex2:words:0:zh":"Thursday","grammar:3287:ex2:words:0:note":"もくようび","grammar:3287:ex2:words:0:pos":"noun","grammar:3287:ex2:words:1:zh":"(point in time)","grammar:3287:ex2:words:1:pos":"particle","grammar:3287:ex2:words:2:zh":"friend","grammar:3287:ex2:words:2:note":"ともだち","grammar:3287:ex2:words:2:pos":"noun","grammar:3287:ex2:words:3:zh":"with","grammar:3287:ex2:words:3:note":"the other person in a shared action","grammar:3287:ex2:words:3:pos":"particle","grammar:3287:ex2:words:4:zh":"meet","grammar:3287:ex2:words:4:note":"あう; dictionary form","grammar:3287:ex2:words:4:pos":"verb","grammar:3287:ex2:words:5:zh":"intend to","grammar:3287:ex2:words:5:note":"〜つもり","grammar:3287:ex2:words:5:pos":"noun","grammar:3287:ex2:words:6:zh":"(polite form)","grammar:3287:ex2:words:6:pos":"copula","grammar:3287:ex2:points:0":"〜と会う：to meet with…","grammar:3287:ex2:points:1":"〜つもりです：to plan to…","grammar:3287:ex3:trans":"I'll finish my homework on Thursday.","grammar:3287:ex3:structure":"timeに＋nounを＋終わらせます. 「終わらせる」 is the causative form of 「終わる」, meaning to make something end.","grammar:3287:ex3:words:0:zh":"Thursday","grammar:3287:ex3:words:0:note":"もくようび","grammar:3287:ex3:words:0:pos":"noun","grammar:3287:ex3:words:1:zh":"(point in time)","grammar:3287:ex3:words:1:pos":"particle","grammar:3287:ex3:words:2:zh":"homework","grammar:3287:ex3:words:2:note":"しゅくだい","grammar:3287:ex3:words:2:pos":"noun","grammar:3287:ex3:words:3:zh":"(object marker)","grammar:3287:ex3:words:3:pos":"particle","grammar:3287:ex3:words:4:zh":"finish / make something end","grammar:3287:ex3:words:4:note":"おわらせます; causative of 終わる","grammar:3287:ex3:words:4:pos":"verb","grammar:3287:ex3:points:0":"終わらせる：to finish, to make something end (the causative transitive verb of 終わる)","grammar:3287:ex3:points:1":"〜に: at … (point in time)","grammar:3287:ex4:trans":"What are you doing Thursday night?","grammar:3287:ex4:structure":"〔木曜の夜〕＋は＋何＋を＋しますか。","grammar:3287:ex4:words:0:zh":"Thursday","grammar:3287:ex4:words:0:note":"もくよう","grammar:3287:ex4:words:0:pos":"noun","grammar:3287:ex4:words:1:zh":"'s","grammar:3287:ex4:words:1:pos":"particle","grammar:3287:ex4:words:2:zh":"evening","grammar:3287:ex4:words:2:note":"よる","grammar:3287:ex4:words:2:pos":"noun","grammar:3287:ex4:words:3:zh":"(topic marker)","grammar:3287:ex4:words:3:pos":"particle","grammar:3287:ex4:words:4:zh":"what","grammar:3287:ex4:words:4:note":"なに","grammar:3287:ex4:words:4:pos":"question word","grammar:3287:ex4:words:5:zh":"(object marker)","grammar:3287:ex4:words:5:pos":"particle","grammar:3287:ex4:words:6:zh":"do?","grammar:3287:ex4:words:6:note":"question","grammar:3287:ex4:words:6:pos":"verb","grammar:3287:ex4:points:0":"木曜の夜：Thursday night","grammar:3287:ex4:points:1":"何をしますか：what will you do","grammar:3287:ex5:trans":"Thursday is a special day.","grammar:3287:ex5:structure":"nounは＋na-adjective＋noun＋です。","grammar:3287:ex5:words:0:zh":"Thursday","grammar:3287:ex5:words:0:note":"もくようび","grammar:3287:ex5:words:0:pos":"noun","grammar:3287:ex5:words:1:zh":"(topic marker)","grammar:3287:ex5:words:1:pos":"particle","grammar:3287:ex5:words:2:zh":"special","grammar:3287:ex5:words:2:note":"とくべつ","grammar:3287:ex5:words:2:pos":"na-adjective","grammar:3287:ex5:words:3:zh":"day","grammar:3287:ex5:words:3:note":"ひ","grammar:3287:ex5:words:3:pos":"noun","grammar:3287:ex5:words:4:zh":"is","grammar:3287:ex5:words:4:pos":"copula","grammar:3287:ex5:points:0":"特別な日：a special day","grammar:3287:ex5:points:1":"木曜日：Thursday","exam:3287:zh":"The day after Wednesday is Thursday.","exam:3287:why":"「木曜」 is Thursday, which comes after Wednesday. 「金曜」 is Friday, one day later than Thursday."},"3288":{"example:3288:exzh":"I hurt my wrist.","example:3288:exzh2":"He's wearing a watch on his wrist.","example:3288:exzh3":"It hurts when I move my wrist.","example:3288:exzh4":"Please be careful with your wrists when you exercise.","example:3288:exzh5":"Let's do some wrist stretches."},"3291":{"example:3291:exzh":"The doctor prescribed a new medication.","example:3291:exzh2":"Prescription drugs are covered by insurance.","example:3291:exzh3":"She followed that and received a prescription.","example:3291:exzh4":"Please take it carefully as prescribed.","example:3291:exzh5":"I was given an explanation about the new prescription."},"3292":{"example:3292:exzh":"Animals live by instinct.","example:3292:exzh2":"Instinct sometimes overrides reason.","example:3292:exzh3":"He sensed the danger instinctively.","example:3292:exzh4":"It's important to follow your instincts.","example:3292:exzh5":"Please listen to the voice of your instincts."},"3293":{"example:3293:exzh":"I'm charging my smartphone.","example:3293:exzh2":"This battery charges quickly.","example:3293:exzh3":"Can I charge my smartphone?","example:3293:exzh4":"The battery is about to die, so I'll charge it quickly.","example:3293:exzh5":"I need to charge it to play games."},"3294":{"example:3294:exzh":"There's a meeting on Tuesday.","example:3294:exzh2":"He's looking forward to Tuesday.","example:3294:exzh3":"I'm having lunch with a friend on Tuesday.","example:3294:exzh4":"I'll watch TV on Tuesday night.","example:3294:exzh5":"Tuesday is a busy day.","grammar:3294:ex:trans":"There's a meeting on Tuesday.","grammar:3294:ex:structure":"timeに＋nounが＋あります. 「〜がある」 expresses that an event exists / is held.","grammar:3294:ex:explain":"The point here is the particle 「に」 marking a point in time and the existential pattern 「〜がある」. In 「火曜に」, 「に」 marks the time when the action or event happens, i.e. on Tuesday, and 「会議がある」＝there is a meeting, with 「会議」 marked by 「が」. The whole sentence 「火曜に会議があります」＝there is a meeting on Tuesday. Note that 「に」 is added only with specific time points such as days of the week, dates, and clock times; relative time words like 「今日」「明日」「毎日」 usually take no 「に」. 「〜に〜がある」 is a common frame for saying that something happens at a certain time.","grammar:3294:ex:words:0:zh":"Tuesday","grammar:3294:ex:words:0:note":"かよう","grammar:3294:ex:words:0:pos":"noun","grammar:3294:ex:words:1:zh":"(point in time)","grammar:3294:ex:words:1:pos":"particle","grammar:3294:ex:words:2:zh":"meeting","grammar:3294:ex:words:2:note":"かいぎ","grammar:3294:ex:words:2:pos":"noun","grammar:3294:ex:words:3:zh":"(nominative)","grammar:3294:ex:words:3:pos":"particle","grammar:3294:ex:words:4:zh":"there is / are","grammar:3294:ex:words:4:note":"exists / there is","grammar:3294:ex:words:4:pos":"verb","grammar:3294:ex:points:0":"〜に: at … (point in time)","grammar:3294:ex:points:1":"会議がある：there is a meeting","grammar:3294:ex2:trans":"He's looking forward to Tuesday.","grammar:3294:ex2:structure":"〜は＋nounを＋楽しみにしています. 「〜を楽しみにする」＝to look forward to…","grammar:3294:ex2:words:0:zh":"he","grammar:3294:ex2:words:0:note":"かれ","grammar:3294:ex2:words:0:pos":"pronoun","grammar:3294:ex2:words:1:zh":"(topic marker)","grammar:3294:ex2:words:1:pos":"particle","grammar:3294:ex2:words:2:zh":"Tuesday","grammar:3294:ex2:words:2:note":"かよう","grammar:3294:ex2:words:2:pos":"noun","grammar:3294:ex2:words:3:zh":"(object marker)","grammar:3294:ex2:words:3:pos":"particle","grammar:3294:ex2:words:4:zh":"looking forward to","grammar:3294:ex2:words:4:note":"〜を楽しみにする","grammar:3294:ex2:words:4:pos":"verb","grammar:3294:ex2:points:0":"〜を楽しみにする: to look forward to…","grammar:3294:ex2:points:1":"楽しみにしています：is looking forward to it","grammar:3294:ex3:trans":"I'm having lunch with a friend on Tuesday.","grammar:3294:ex3:structure":"timeに＋nounと＋nounを＋します。","grammar:3294:ex3:words:0:zh":"Tuesday","grammar:3294:ex3:words:0:note":"かよう","grammar:3294:ex3:words:0:pos":"noun","grammar:3294:ex3:words:1:zh":"(point in time)","grammar:3294:ex3:words:1:pos":"particle","grammar:3294:ex3:words:2:zh":"friend","grammar:3294:ex3:words:2:note":"ともだち","grammar:3294:ex3:words:2:pos":"noun","grammar:3294:ex3:words:3:zh":"with","grammar:3294:ex3:words:3:pos":"particle","grammar:3294:ex3:words:4:zh":"lunch","grammar:3294:ex3:words:4:note":"loanword","grammar:3294:ex3:words:4:pos":"noun","grammar:3294:ex3:words:5:zh":"(object marker)","grammar:3294:ex3:words:5:pos":"particle","grammar:3294:ex3:words:6:zh":"do / have","grammar:3294:ex3:words:6:note":"ランチをする＝to have lunch","grammar:3294:ex3:words:6:pos":"verb","grammar:3294:ex3:points:0":"〜と: with… (together)","grammar:3294:ex3:points:1":"ランチをする：to have lunch","grammar:3294:ex4:trans":"I'll watch TV on Tuesday night.","grammar:3294:ex4:structure":"〔火曜の夜〕＋は＋nounを＋見ます。","grammar:3294:ex4:words:0:zh":"Tuesday","grammar:3294:ex4:words:0:note":"かよう","grammar:3294:ex4:words:0:pos":"noun","grammar:3294:ex4:words:1:zh":"'s","grammar:3294:ex4:words:1:pos":"particle","grammar:3294:ex4:words:2:zh":"evening","grammar:3294:ex4:words:2:note":"よる","grammar:3294:ex4:words:2:pos":"noun","grammar:3294:ex4:words:3:zh":"(topic marker)","grammar:3294:ex4:words:3:pos":"particle","grammar:3294:ex4:words:4:zh":"TV","grammar:3294:ex4:words:4:note":"loanword","grammar:3294:ex4:words:4:pos":"noun","grammar:3294:ex4:words:5:zh":"(object marker)","grammar:3294:ex4:words:5:pos":"particle","grammar:3294:ex4:words:6:zh":"look","grammar:3294:ex4:words:6:note":"みます","grammar:3294:ex4:words:6:pos":"verb","grammar:3294:ex4:points:0":"火曜の夜：Tuesday night","grammar:3294:ex4:points:1":"テレビを見る：to watch TV","grammar:3294:ex5:trans":"Tuesday is a busy day.","grammar:3294:ex5:structure":"noun は＋i-adjective＋noun＋です.","grammar:3294:ex5:words:0:zh":"Tuesday","grammar:3294:ex5:words:0:note":"かよう","grammar:3294:ex5:words:0:pos":"noun","grammar:3294:ex5:words:1:zh":"(topic marker)","grammar:3294:ex5:words:1:pos":"particle","grammar:3294:ex5:words:2:zh":"busy","grammar:3294:ex5:words:2:note":"いそがしい","grammar:3294:ex5:words:2:pos":"adjective","grammar:3294:ex5:words:3:zh":"day","grammar:3294:ex5:words:3:note":"ひ","grammar:3294:ex5:words:3:pos":"noun","grammar:3294:ex5:words:4:zh":"is","grammar:3294:ex5:words:4:pos":"copula","grammar:3294:ex5:points:0":"忙しい日：a busy day","grammar:3294:ex5:points:1":"火曜：Tuesday","exam:3294:zh":"The day after Monday is Tuesday.","exam:3294:why":"「火曜」 is Tuesday, which comes right after Monday. 「水曜」 is Wednesday, one day later than the correct answer."},"3295":{"example:3295:exzh":"He has a responsibility to compensate for the damage.","example:3295:exzh2":"I don't know how to make up for it.","example:3295:exzh3":"She is trying to make up for her past mistakes.","example:3295:exzh4":"Making amends takes time.","example:3295:exzh5":"He decided to make up for his mistake."},"3296":{"example:3296:exzh":"This is appropriate attire for the occasion.","example:3296:exzh2":"I can't find a suitable answer.","example:3296:exzh3":"I think he's a suitable candidate.","example:3296:exzh4":"Appropriate action is required.","example:3296:exzh5":"She showed an appropriate attitude."},"3297":{"example:3297:exzh":"His paper was highly praised.","example:3297:exzh2":"Writing a paper is hard.","example:3297:exzh3":"She submitted her paper.","example:3297:exzh4":"I'll review the paper.","example:3297:exzh5":"The topic of this paper is very interesting."},"3298":{"example:3298:exzh":"Dinosaurs lived long ago.","example:3298:exzh2":"Dinosaur fossils were found.","example:3298:exzh3":"Kids like dinosaurs.","example:3298:exzh4":"I want to go to the dinosaur museum.","example:3298:exzh5":"There are many kinds of dinosaurs."},"3299":{"example:3299:exzh":"He has a logical way of thinking.","example:3299:exzh2":"When logic doesn't get through, confusion arises.","example:3299:exzh3":"This problem can be solved logically.","example:3299:exzh4":"Her logic is always clear.","example:3299:exzh5":"If you ignore logic, misunderstandings arise."}};